WITH base AS (SELECT *, CASE WHEN location IN ('Bangkok', 'Berlin') THEN 'Priority' ELSE 'Other' END AS location_group, ROUND(budget * 0.85, 2) AS budget_scaled, COALESCE(dept_name, 'NONE') AS dept_name_filled FROM departments WHERE location IS DISTINCT FROM 'Chiang Mai' AND budget < 1672000) SELECT * FROM (SELECT dept_name, location, budget_scaled FROM base) src PIVOT (AVG(budget_scaled) AS value_sum, COUNT(1) AS n FOR location IN ('Chiang Mai' AS chiang_mai, 'Tokyo' AS tokyo));
